  import { Logger } from '../services/logger.service';

  const logger = new Logger('PackageLoader');

  export function loadPackage(
    packageName: string,
    context: string,
    loaderFn?: Function,
  ) {
    try {
      return loaderFn ? loaderFn() : require(packageName);
    } catch (e) {
      logger.error(`The "${packageName}" package is missing. Please, make sure to install it to take advantage of ${context}.`);
      Logger.flush();
      process.exit(1);
    }
  }
